/**
 * @name Code injection via eval/exec in CFFI
 * @description User-controlled input flowing to eval/exec/compile can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/cffi-code-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module EvalInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for eval, exec, compile calls
    exists(API::CallNode call |
      call = API::builtin(["eval", "exec", "compile"]).getACall() or
      call = API::moduleImport("builtins").getMember(["eval", "exec", "compile"]).getACall()
    |
      // The first argument to eval/exec/compile is the code to execute
      sink = call.getArg(0)
    )
  }
}

module EvalInjectionFlow = TaintTracking::Global<EvalInjectionConfig>;
import EvalInjectionFlow::PathGraph

from EvalInjectionFlow::PathNode source, EvalInjectionFlow::PathNode sink
where EvalInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code injection via eval/exec from $@.", source.getNode(), "user input"

/**
 * @name C code injection via CFFI code generation
 * @description User-controlled input flowing to C code generation can lead to arbitrary C code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/cffi-code-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module CffiCodeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for C code generation in cffi modules
    exists(DataFlow::CallCfgNode call |
      // C code generation functions in cffi
      call = API::moduleImport("cffi").getMember(["recompiler", "cparser", "api", "model"]).getACall() or
      // String operations that could build C code
      call = API::builtin("str").getMember(["format", "join", "replace", "__add__"]).getACall() or
      // File write operations for C files
      call = API::moduleImport("io").getMember("open").getMember("write").getACall() or
      // exec/eval with potentially generated C code
      call = API::builtin(["exec", "eval", "compile"]).getACall()
    |
      sink = call.getArg(0)  // First argument could be the code being generated
    )
  }
}

module CffiCodeInjectionFlow = TaintTracking::Global<CffiCodeInjectionConfig>;
import CffiCodeInjectionFlow::PathGraph

from CffiCodeInjectionFlow::PathNode source, CffiCodeInjectionFlow::PathNode sink
where CffiCodeInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "C code injection from $@.", source.getNode(), "user input"
